CREATE SCHEMA IF NOT EXISTS allbot;

CREATE TABLE IF NOT EXISTS allbot.settings (guild_id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS allbot.tickets (
  id SERIAL PRIMARY KEY, guild_id TEXT, channel_id TEXT, user_id TEXT, type TEXT,
  status TEXT DEFAULT 'open', claimed_by TEXT, answers TEXT, transcript TEXT,
  created_at BIGINT, closed_at BIGINT, closed_by TEXT);
CREATE TABLE IF NOT EXISTS allbot.applications (
  id SERIAL PRIMARY KEY, guild_id TEXT, form_id TEXT, user_id TEXT, answers TEXT,
  status TEXT DEFAULT 'pending', reviewed_by TEXT, message_id TEXT, channel_id TEXT, created_at BIGINT);
CREATE TABLE IF NOT EXISTS allbot.levels (guild_id TEXT, user_id TEXT, xp INTEGER DEFAULT 0, PRIMARY KEY (guild_id, user_id));
CREATE TABLE IF NOT EXISTS allbot.warnings (id SERIAL PRIMARY KEY, guild_id TEXT, user_id TEXT, mod_id TEXT, reason TEXT, created_at BIGINT);
CREATE TABLE IF NOT EXISTS allbot.giveaways (
  id SERIAL PRIMARY KEY, guild_id TEXT, channel_id TEXT, message_id TEXT, prize TEXT,
  winners INTEGER, ends_at BIGINT, entries TEXT DEFAULT '[]', ended INTEGER DEFAULT 0, winner_ids TEXT, host_id TEXT);
CREATE TABLE IF NOT EXISTS allbot.stream_state (guild_id TEXT, key TEXT, value TEXT, PRIMARY KEY (guild_id, key));

CREATE TABLE IF NOT EXISTS allbot.wheel_spins (id TEXT PRIMARY KEY,guild_id TEXT NOT NULL,user_id TEXT NOT NULL,data TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS allbot.member_events (id SERIAL PRIMARY KEY,guild_id TEXT NOT NULL,user_id TEXT NOT NULL,action TEXT NOT NULL,data TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS member_events_guild ON allbot.member_events(guild_id,id);

CREATE TABLE IF NOT EXISTS allbot.panel_users (guild_id TEXT NOT NULL,user_id TEXT NOT NULL,discord_name TEXT NOT NULL,salt TEXT NOT NULL,hash TEXT NOT NULL,disabled INTEGER NOT NULL DEFAULT 0,created_at BIGINT,updated_at BIGINT,PRIMARY KEY(guild_id,user_id));
CREATE TABLE IF NOT EXISTS allbot.panel_invites (id TEXT PRIMARY KEY,guild_id TEXT NOT NULL,user_id TEXT NOT NULL,salt TEXT NOT NULL,hash TEXT NOT NULL,expires_at BIGINT NOT NULL,used_at BIGINT NOT NULL DEFAULT 0,created_by TEXT NOT NULL,created_at BIGINT);
CREATE TABLE IF NOT EXISTS allbot.dev_registry (id TEXT PRIMARY KEY,guild_id TEXT NOT NULL,data TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at BIGINT,updated_at BIGINT);
CREATE TABLE IF NOT EXISTS allbot.dev_presence (guild_id TEXT NOT NULL,user_id TEXT NOT NULL,discord_name TEXT NOT NULL,total_ms BIGINT NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 0,last_seen BIGINT NOT NULL,PRIMARY KEY(guild_id,user_id));
CREATE TABLE IF NOT EXISTS allbot.panel_media (id TEXT PRIMARY KEY,guild_id TEXT NOT NULL,user_id TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,content TEXT NOT NULL,created_at BIGINT,scope TEXT NOT NULL DEFAULT 'shared');
CREATE TABLE IF NOT EXISTS allbot.dev_gate (guild_id TEXT PRIMARY KEY, salt TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS allbot.dev_gate_attempts (guild_id TEXT NOT NULL, subject TEXT NOT NULL, failures INTEGER NOT NULL, until BIGINT NOT NULL, PRIMARY KEY(guild_id,subject));
CREATE TABLE IF NOT EXISTS allbot.site_audit (id SERIAL PRIMARY KEY, guild_id TEXT NOT NULL, user_id TEXT NOT NULL, module TEXT NOT NULL, action TEXT NOT NULL, details TEXT NOT NULL, created_at BIGINT);
CREATE INDEX IF NOT EXISTS site_audit_lookup ON allbot.site_audit(guild_id,module,id);
CREATE TABLE IF NOT EXISTS allbot.stream_accounts (guild_id TEXT NOT NULL, platform TEXT NOT NULL, user_id TEXT NOT NULL, handle TEXT NOT NULL, PRIMARY KEY(guild_id,platform,user_id));
CREATE TABLE IF NOT EXISTS allbot.dev_tasks (id SERIAL PRIMARY KEY, guild_id TEXT NOT NULL, user_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT, status TEXT DEFAULT 'todo', notes TEXT DEFAULT '', checklist TEXT DEFAULT '[]', attachments TEXT DEFAULT '[]', channel_id TEXT, message_id TEXT, sync_error TEXT DEFAULT '', legacy_id TEXT, version INTEGER DEFAULT 1, created_at BIGINT, updated_at BIGINT);
CREATE TABLE IF NOT EXISTS allbot.dev_comments (id SERIAL PRIMARY KEY, guild_id TEXT NOT NULL, task_id INTEGER NOT NULL, user_id TEXT NOT NULL, author_type TEXT NOT NULL, body TEXT NOT NULL, created_at BIGINT);
CREATE INDEX IF NOT EXISTS dev_comments_task ON allbot.dev_comments(guild_id,task_id);
CREATE TABLE IF NOT EXISTS allbot.dev_history (id SERIAL PRIMARY KEY, guild_id TEXT, task_id INTEGER, user_id TEXT, status TEXT, created_at BIGINT);
CREATE TABLE IF NOT EXISTS allbot.dev_files (id SERIAL PRIMARY KEY, guild_id TEXT NOT NULL, task_id INTEGER NOT NULL, user_id TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, content TEXT NOT NULL, created_at BIGINT);
CREATE INDEX IF NOT EXISTS dev_files_task ON allbot.dev_files(guild_id,task_id);
CREATE TABLE IF NOT EXISTS allbot.dev_audit (id SERIAL PRIMARY KEY, guild_id TEXT NOT NULL, task_id INTEGER NOT NULL, user_id TEXT NOT NULL, action TEXT NOT NULL, details TEXT NOT NULL, created_at BIGINT);
CREATE INDEX IF NOT EXISTS dev_audit_guild ON allbot.dev_audit(guild_id);
CREATE TABLE IF NOT EXISTS allbot.dev_deleted (guild_id TEXT NOT NULL, task_id INTEGER NOT NULL, user_id TEXT NOT NULL, created_at BIGINT, PRIMARY KEY(guild_id,task_id));
CREATE TABLE IF NOT EXISTS allbot.dev_planning (guild_id TEXT NOT NULL, task_id INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(guild_id,task_id));
CREATE TABLE IF NOT EXISTS allbot.dev_images (task_id INTEGER PRIMARY KEY, guild_id TEXT NOT NULL, mime TEXT NOT NULL, content TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS dev_tasks_guild ON allbot.dev_tasks(guild_id);
CREATE INDEX IF NOT EXISTS dev_tasks_cooldown ON allbot.dev_tasks(guild_id,user_id,created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS dev_tasks_legacy ON allbot.dev_tasks(guild_id,legacy_id);

ALTER TABLE allbot.panel_media ADD COLUMN IF NOT EXISTS scope TEXT NOT NULL DEFAULT 'shared';
-- Separate existing references without changing the original GIF/image bytes.
ALTER TABLE allbot.panel_media ADD COLUMN IF NOT EXISTS scope TEXT NOT NULL DEFAULT 'shared';
CREATE INDEX IF NOT EXISTS panel_media_scope ON allbot.panel_media(guild_id,scope,created_at);
SELECT m.id||'-birthdays',m.guild_id,m.user_id,m.name,m.mime,m.content,m.created_at,'birthdays'
FROM allbot.panel_media m JOIN allbot.settings s ON s.guild_id=m.guild_id
WHERE m.scope='shared' AND s.data::jsonb #>> '{birthdays,mediaId}'=m.id
ON CONFLICT(id) DO NOTHING;
UPDATE allbot.settings s SET data=jsonb_set(s.data::jsonb,'{birthdays,mediaId}',to_jsonb(m.id||'-birthdays'))::text
FROM allbot.panel_media m WHERE m.guild_id=s.guild_id AND m.scope='shared' AND s.data::jsonb #>> '{birthdays,mediaId}'=m.id;
SELECT DISTINCT m.id||'-slideshow',m.guild_id,m.user_id,m.name,m.mime,m.content,m.created_at,'slideshow'
FROM allbot.settings s CROSS JOIN LATERAL jsonb_array_elements(COALESCE(s.data::jsonb #> '{slideshow,slides}','[]'::jsonb)) slide
JOIN allbot.panel_media m ON m.guild_id=s.guild_id AND m.id=slide->>'mediaId'
WHERE m.scope='shared' ON CONFLICT(id) DO NOTHING;
UPDATE allbot.settings s SET data=jsonb_set(s.data::jsonb,'{slideshow,slides}',(
 SELECT COALESCE(jsonb_agg(CASE WHEN m.id IS NOT NULL THEN jsonb_set(slide,'{mediaId}',to_jsonb(m.id||'-slideshow')) ELSE slide END ORDER BY ord),'[]'::jsonb)
 FROM jsonb_array_elements(s.data::jsonb #> '{slideshow,slides}') WITH ORDINALITY AS a(slide,ord)
 LEFT JOIN allbot.panel_media m ON m.guild_id=s.guild_id AND m.id=slide->>'mediaId' AND m.scope='shared'
))::text WHERE jsonb_typeof(s.data::jsonb #> '{slideshow,slides}')='array';


CREATE TABLE IF NOT EXISTS allbot.query_templates (key TEXT PRIMARY KEY, statement TEXT NOT NULL, parameters INTEGER NOT NULL);
REVOKE ALL ON SCHEMA allbot FROM anon, authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA allbot FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.allbot_execute(query_key TEXT, params JSONB DEFAULT '[]'::JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, allbot AS $function$
DECLARE template allbot.query_templates%ROWTYPE; statement TEXT; result JSONB; idx INTEGER; pieces TEXT[];
BEGIN
  SELECT * INTO template FROM allbot.query_templates WHERE key=query_key;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown query'; END IF;
  IF jsonb_typeof(params) IS DISTINCT FROM 'array' OR jsonb_array_length(params)<>template.parameters THEN RAISE EXCEPTION 'Invalid parameters'; END IF;
  pieces := regexp_split_to_array(template.statement, E'\\$[0-9]+');
  statement := pieces[1];
  IF template.parameters>0 THEN
    FOR idx IN 1..template.parameters LOOP
      statement := statement || quote_nullable(params->>(idx-1)) || pieces[idx+1];
    END LOOP;
  END IF;
  IF statement !~* '^SELECT' THEN statement := statement || ' RETURNING *'; END IF;
  EXECUTE 'WITH result AS ('||statement||') SELECT coalesce(jsonb_agg(to_jsonb(result)),''[]''::jsonb) FROM result' INTO result;
  RETURN jsonb_build_object('rows',result,'rowCount',jsonb_array_length(result));
END;
$function$;
REVOKE ALL ON FUNCTION public.allbot_execute(TEXT,JSONB) FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA allbot TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA allbot TO service_role;
REVOKE INSERT, UPDATE, DELETE ON allbot.query_templates FROM service_role;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA allbot TO service_role;
GRANT EXECUTE ON FUNCTION public.allbot_execute(TEXT,JSONB) TO service_role;

